# aeneid-065 (IX.107-223): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Naves nymphae. Nisus et Euryalus'
PART = "The Ships Become Nymphs; Nisus and Euryalus (IX.107–223)"
TITLE_EN = "The Ships Become Nymphs; Nisus and Euryalus — Aeneid IX.107–223"
ABOUT = ("The day Jupiter promised arrives. As Turnus brings his torches against the Trojan fleet, a strange light "
"flashes, a great cloud sweeps across the sky from the east with the dancing bands of Mount Ida in it, and a voice rings "
"out over both armies: the Trojans need not defend the ships, for Turnus will sooner burn the sea than these sacred pines; "
"the ships are to go free as goddesses of the sea, at their mother's bidding. At once they snap their cables, dive like "
"dolphins, and come up again as sea-nymphs, one for every bronze-beaked prow. The Rutulians are struck with terror, "
"Messapus's horses panic, and even the river Tiber draws back. Turnus alone keeps his nerve. The portent, he tells his "
"men, is aimed at the Trojans: Jupiter has taken away their last way of escape, and the land is in Italian hands. He has "
"his own destiny to set against theirs, to wipe out the race that stole his bride, as the sons of Atreus once avenged "
"theirs; he needs no armour forged by Vulcan, no thousand ships and no wooden horse, but will storm the walls by daylight. "
"For the night, Messapus is to blockade the gates and ring the camp with fires, and the Rutulian watch passes it in wine "
"and games. On the walls the Trojans keep anxious guard under Mnestheus and Serestus. At one gate stand Nisus and the young "
"Euryalus, devoted friends. Nisus, restless for some great deed, sees the enemy sunk in sleep and plans to slip through "
"their lines to find Aeneas at Pallanteum. Euryalus insists on going with him; Nisus tries to dissuade him for his youth "
"and for his mother's sake, who alone of the Trojan mothers followed her son to Italy, but Euryalus will not be moved. "
"They hand their post to the relief and go together to find the prince.")

U = [
(109, 'depellere taedas.',
 "So it was at hand, the promised day, and the times by the Fate\nowed they had completed, when Turnus's outrage the Mother\nwarned from the ships, the sacred, to drive off the torches.",
 "So the promised day had come, and the times the Fate had fixed were fulfilled, when Turnus's outrage warned the Mother to drive the torches from her sacred ships.",
 """A new paragraph in Greenough. 'Ergo', 'so then', picking up Jupiter's promise to Cybele at the end of the last part (9.94–106). 'complerant' = 'compleverant', the syncopated pluperfect. 'Parcae', 'of the Fate' (or dative, 'owed to the Fate'), one of the three Parcae who spin each life; 'tempora… debita', the span she had set. 'Turni iniuria', 'Turnus's outrage', his attack on the ships. 'Matrem', the Great Mother, Cybele, from whose sacred grove on Ida the ships were built. 'admonuit… depellere', 'warned (her) to drive off', a poetic infinitive with a verb of urging. 'ratibus sacris', dative with a verb of removing. Elisions 'Erg(o) aderat', 'Turn(i) iniuria'."""),
(113, 'agmina complet:',
 "Here first a new light before their eyes flashed out, and a huge,\nseen from the Dawn the sky to run across, cloud,\nand Ida's dancing bands; then a voice dreadful through the air\nfell, and of the Trojans and Rutulians the ranks fills:",
 "Then first a strange light flashed before their eyes, and a vast cloud was seen running across the sky from the east, and in it the dancing bands of Ida; then a fearful voice fell through the air and filled the ranks of Trojans and Rutulians alike:",
 """'oculis', 'before (their) eyes', dative. 'ingens… nimbus', 'a huge cloud', the adjective ending 110 and the noun ending 111; 'visus (est)… transcurrere', 'was seen to run across'. 'ab Aurora', 'from the Dawn', from the east, where Ida and Cybele's Phrygia lie. 'Idaeique chori', 'and the bands of Ida', also seen: the Corybantes, the goddess's frenzied dancers with drums and cymbals. 'vox horrenda… excidit', 'a dreadful voice fell', dropped from the sky. 'Troum', 'of the Trojans', a short genitive plural of 'Tros', two syllables. The change of tense to 'complet' is the vivid present. Elision 'Rutulorumqu(e) agmina'."""),
(116, 'dabitur pinus.',
 "“Do not be anxious my to defend, Teucrians, ships,\nnor arm your hands: the seas sooner to burn up to Turnus\nthan the sacred will be granted pines.",
 "“Trojans, do not trouble to defend my ships, and take no weapons in your hands: Turnus will be allowed to burn up the sea before these sacred pines.",
 """The speech of the Mother (114–117). 'Ne trepidate… defendere', 'do not be in a flurry to defend', 'ne' with the imperative, the poetic form of a prohibition (prose says 'nolite defendere'); 'trepido' with an infinitive, to hurry about something in alarm. 'meas… navis', 'my ships', enclosing 'Teucri, defendere'; 'navis' is accusative plural in '-is'. 'neve armate manus', 'and do not arm your hands'. 'ante… quam', 'sooner… than', split apart (tmesis): 'dabitur Turno', 'it will be granted to Turnus', to burn the very seas before the ships. 'pinus', 'pines', the ships as the trees they were. Elisions 'nev(e) armate', 'mari(a) ante', 'ant(e) exurere'."""),
(117, 'deae pelagi:',
 "You go, released,\ngo, goddesses of the sea:",
 "Go, you are free; go, goddesses of the sea:",
 """'Vos ite solutae', 'go, you, set loose', from your moorings; 'solutae' agrees with the ships, feminine like 'naves'. The repeated 'ite… ite' (anaphora) is the release itself, spoken as a command. 'deae pelagi', 'goddesses of the sea', the vocative fulfilling Jupiter's promise in the last part that the ships which reached Italy would become 'magni… aequoris… deas', goddesses of the great sea (9.102–103). 'pelagi', from the Greek-born 'pelagus', 'open sea'. No elisions."""),
(120, 'ima petunt.',
 "the Mother bids.” And her own each\nat once the ships break their cables from the banks,\nand in dolphins' manner, with plunged into the water beaks,\nthe depths they seek.",
 "It is your mother who bids you.” And at once each ship broke its cables from the bank, and like dolphins they plunged their beaks under and made for the depths.",
 """The print has 'iubet. ”Et', a misprint for 'iubet.” Et', corrected here: the closing mark is set after the space and joined to the next word (as 8.404, 9.22, 9.38). t keeps the print; since the mark is joined to 'Et', this unit runs on to the end of the narrative sentence. 'genetrix iubet', 'the Mother bids', Cybele naming herself in the third person, as a decree. 'sua quaeque… puppes', 'each ship its own', 'quaeque' in apposition to the plural subject. 'ripis', 'from the banks', ablative of separation. 'delphinum modo', 'in the manner of dolphins'. 'demersis… rostris', ablative absolute, 'their beaks plunged under', the bronze rams at the prow. 'aequora… ima', 'the lowest waters', the depths. No elisions."""),
(122, 'pontoque feruntur.',
 "From there maiden (a marvellous portent)\nas many as before bronze had stood at the shore prows,\ngive themselves back, so many forms, and over the sea are borne.",
 "Then — a wonderful portent — as many maidens' forms as there had been bronze prows moored at the shore rose up again and were carried out over the sea.",
 """'Hinc', 'next', 'from that point'. 'virgineae… facies', 'maiden forms', the subject, set three lines apart; 'quot… totidem', 'as many… so many': for every prow that had stood at the shore, one nymph. 'aeratae… prorae', 'bronze-plated prows'. 'mirabile monstrum', 'a marvellous portent', a parenthesis; 'monstrum' is a sign from the gods, not a 'monster'. 'reddunt se', 'give themselves back', reappear. The Latin Library leaves out 121, which recurs at 10.223 where the nymphs meet Aeneas at sea; without it 'totidem' has nothing to answer. Ovid retells the change (Metamorphoses 14). No elisions."""),
(125, 'pedem Tiberinus ab alto.',
 "Were stunned in their hearts the Rutulians, terrified himself\nwith his horses confounded Messapus, hesitates even the river,\nhoarsely sounding, and calls back his foot, Tiberinus, from the deep.",
 "The Rutulians were stunned to the heart; Messapus himself was terrified as his horses bolted in panic; even the river Tiber halted with a hoarse roar and drew his foot back from the sea.",
 """A new paragraph in Greenough. 'Obstipuere' = 'obstipuerunt', the perfect in '-ere' for '-erunt' (you'll see this constantly). 'animis', 'in their hearts', ablative of respect. 'conterritus… Messapus', 'Messapus, terrified', enclosing 'ipse turbatis'; he is the tamer of horses (7.691), so his own horses' panic is the worse. 'turbatis… equis', ablative absolute or of cause. 'rauca sonans', 'sounding hoarse things', a neuter plural used adverbially. 'Tiberinus', the river god, himself afraid: 'revocat pedem', 'calls back his foot', checks his flow. 'ab alto', 'from the deep', from the sea at his mouth. Elision 'Obstipuer(e) animis'."""),
(126, 'fiducia cessit;',
 "But not from bold Turnus did his confidence give way;",
 "But bold Turnus did not lose his confidence;",
 """'At non', 'but not', turning from the panic to the one man unshaken. 'audaci Turno', 'from bold Turnus', dative with 'cessit', 'gave way', 'left'; 'audax' is his standing epithet, as at the opening of the book (9.3). 'fiducia', 'self-confidence'. Virgil repeats the line almost word for word at 10.276, 'Haud tamen audaci Turno fiducia cessit', when Turnus sees Aeneas's fleet arriving: his nerve is his mark. No elisions."""),
(127, 'increpat ultro:',
 "unbidden their spirits he raises with words, and rebukes them, unbidden:",
 "he went further, raising their courage with his words, and went so far as to rebuke them:",
 """'ultro… ultro', 'beyond (what was asked)', 'unprompted', set at both ends of the line: he does more than hold firm; he takes the lead in heartening them, and even scolds them for their fear. 'animos tollit', 'raises their spirits'. 'dictis', 'with words', ablative of means. 'increpat', 'rebukes', 'chides'. The verb of speaking now leads straight into the speech. Elisions 'ultr(o) animos', 'atqu(e) increpat'."""),
(130, 'exspectans Rutulos.',
 "“The Trojans these portents aim at; from them Jupiter himself\nthe help, the accustomed, has snatched, not the weapons nor the fires\nawaiting of the Rutulians.",
 "“It is the Trojans these portents strike at: Jupiter himself has robbed them of the help they were used to, without waiting for Rutulian spears and fires.",
 """Turnus's speech opens (128–158); he turns the omen against the Trojans. 'Troianos', set first: the Trojans, not us. 'his', 'from them', dative of disadvantage with 'eripuit', 'snatched away'. 'auxilium solitum', 'their accustomed help', the ships, their usual resort, flight by sea. 'non… exspectans', 'not waiting for', Jupiter did not wait for our spears and fires to do it. The Latin Library prints 'ignis exspectant', a new clause, 'they (the ships) do not wait for Rutulian spears and fires'; the sense changes, the point is the same. 'ignes' is Greenough's accusative plural. Elisions 'solit(um) eripuit', 'nequ(e) ignes'."""),
(131, 'adempta est.',
 "So the seas are pathless to the Teucrians,\nnor is there hope any of flight: of the world the part, one of two, is taken away.",
 "So the sea is closed to the Trojans and they have no hope of flight; half of the world is taken from them.",
 """'Ergo maria invia (sunt) Teucris', 'so the seas are pathless for the Trojans', 'sunt' left out, as so often, and 'Teucris' dative. 'invia', 'without a way'. 'nec spes ulla fugae (est)', 'nor is there any hope of flight'. 'rerum pars altera', 'the one of two parts of things', 'alter' of a pair: the world is land and sea, and the sea is gone. 'adempta est', 'has been taken away', from 'adimo'. Elisions 'mari(a) invia', 'alter(a) adempt(a) est'."""),
(133, 'ferunt Italae.',
 "The land, though, is in our hands; so many thousands, the peoples,\nare bearing arms, of Italy.",
 "And the land is in our hands: so many thousands of Italy's peoples are under arms.",
 """'Terra autem (est) in nostris manibus', 'but the land is in our hands', the other half of 'rerum pars altera'. 'tot milia', 'so many thousands', in apposition to 'gentes… Italae', 'the Italian peoples', whose adjective is held back to the next line. Book 7 ended with the catalogue of these peoples marching to war (7.647–817). 'arma ferunt', 'bear arms', are in the field. Elisions 'Terr(a) autem', 'aut(em) in'."""),
(134, 'responsa deorum:',
 "Not at all me the fateful frighten,\nif any the Phrygians before them flaunt, answers of the gods:",
 "I am not in the least afraid of the fateful oracles of the gods, if the Phrygians have any to flaunt before them:",
 """'Nil', 'not at all', an adverbial accusative. 'fatalia… responsa deorum', 'the fateful answers of the gods', the oracles the Trojans cite for their coming to Italy; the adjective and noun stand a line apart. 'siqua', Greenough's spelling of 'si qua' (as the Latin Library prints it), 'if any', 'qua' the indefinite after 'si', neuter plural. 'Phryges', 'Phrygians', a sneer: the Trojans as soft Asiatics. 'prae se iactant', 'flaunt before them', parade. 'iactant' begins with a consonantal i, so 'se' does not elide. No elisions."""),
(136, 'Ausoniae Troes.',
 "Enough to the fates and to Venus has been given, that have touched the fields\nof fertile Ausonia the Trojans.",
 "The fates and Venus have had their due, in that the Trojans have set foot in the fields of fertile Ausonia.",
 """'sat… datum (est)', 'enough has been given', 'est' left out. 'fatis Venerique', 'to the fates and to Venus', Aeneas's mother and his divine champion. 'quod', 'in that', 'the fact that', explaining 'sat'. 'tetigere' = 'tetigerunt', the '-ere' perfect again. 'arva… Ausoniae', 'the fields of Ausonia', an old name for Italy; 'fertilis', genitive singular with 'Ausoniae'. Turnus concedes the oracle its letter (they have reached Italy) and no more. 'Troes', two syllables, a Greek nominative plural. No elisions."""),
(138, 'coniuge praerepta:',
 "There are also my own, against them,\nfates for me: with the sword the criminal to cut out race,\nmy bride snatched from me first:",
 "I too have fates of my own to set against theirs: to cut down with the sword a criminal race that has snatched my bride from me:",
 """'Sunt… mihi', 'there are to me', 'I have', the dative of possession (as 'sunt mihi' in Book 1). 'mea contra fata', 'fates of my own on the other side', 'contra' as an adverb. 'exscindere', 'to cut out', 'raze', an infinitive in apposition to 'fata', explaining what his destiny is. 'sceleratam… gentem', 'the criminal race', enclosing 'exscindere'. 'coniuge praerepta', ablative absolute, 'my bride snatched first': Lavinia, promised to Turnus before Aeneas came, given to Aeneas by her father (Book 7). Elision 'scelerat(am) exscindere'."""),
(139, 'arma Mycenis.',
 "nor the sons of Atreus only does it touch,\nthat grief, and to Mycenae only is it allowed to take up arms.",
 "it is not only the sons of Atreus who feel that pain, nor is Mycenae the only city allowed to take up arms.",
 """Turnus casts himself as a new Menelaus. 'Atridas', 'the sons of Atreus', Agamemnon and Menelaus, Greek accusative plural in '-as': Paris took Menelaus's wife Helen, and the Greeks went to war for her. 'iste dolor', 'that grief', the pain of a stolen wife. 'solis… Mycenis', 'to Mycenae alone', dative with 'licet', 'it is permitted', enclosing 'licet capere arma'; Mycenae was Agamemnon's city. The repeated 'solos… solis' drives the point. Elision 'caper(e) arma'."""),
(140, 'satis est:',
 "But to have perished once is enough:",
 "‘But to have perished once is enough,’ they may say:",
 """Turnus answers an objection before it is made: 'periisse semel satis est', 'to have perished once is enough', the Trojans were destroyed once, so they have paid. 'periisse', the perfect infinitive of 'pereo'. The answer follows after the colon, with a twist on 'satis'. In i the objection is set off in single marks inside the speech. No elisions."""),
(142, 'femineum.',
 "to have sinned it ought to have been\nbefore enough, utterly, all but, the race whole hating\nfemale.",
 "it ought to have been enough for them to have sinned once before, and now to hate almost every woman alive.",
 """'peccare fuisset ante satis', 'to sin before should have been enough', 'fuisset' in the sense of 'ought to have been': one offence (Paris's theft of Helen) should have taught them their lesson. 'perosos', 'utterly hating', from 'perodi', with active sense; it agrees with an understood 'eos' (them), the subject of 'peccare': they should have come out of it hating 'genus omne femineum', 'the whole female sex', so that they would never steal a woman again. 'penitus modo non', 'all but entirely', 'modo non' meaning 'almost'. 'femineum' is held over to the next line. No elisions."""),
(144, 'dant animos.',
 "To them this, of the rampart between, confidence\nand of the ditches the delays, of death the partitions slight,\ngive courage.",
 "These men take heart from their trust in the rampart between us, and from the hindrance of their ditches, thin partitions between them and death.",
 """'Quibus', a connecting relative, 'to these men' (you'll keep meeting it at the head of a sentence). 'haec… fiducia', 'this confidence', the subject with 'morae', 'delays', the obstacles that slow an attacker. 'medii… valli', 'of the rampart in between', objective genitive. 'fossarum', 'of the ditches'. 'leti discrimina parva', 'slight partitions from death', in apposition: a ditch and a bank are all that divide them from dying. 'dant animos', 'give (them) courage'. No elisions."""),
(145, 'considere in ignis?',
 "But did they not see the walls of Troy,\nby Neptune's built hand, sink into the fires?",
 "But did they not see the walls of Troy, built by Neptune's own hand, sink down into the flames?",
 """'At non viderunt', 'but did they not see', a question expecting 'yes'. 'moenia Troiae… fabricata', 'the walls of Troy… fashioned': Neptune and Apollo built them for King Laomedon; walls a god built did not save Troy, so a ditch will not save them now. 'Neptuni… manu', 'by Neptune's hand', enclosing 'fabricata'. 'considere in ignis', 'to settle down into the fires', the phrase Aeneas used of the fall of Troy (2.624 'omne mihi visum considere in ignis'). 'ignis', accusative plural in '-is'. Elision 'consider(e) in'."""),
(147, 'trepidantia castra.',
 "“But you, O chosen men, with the sword who to cut the rampart\nmakes ready and with me invades the panicking camp?",
 "“But you, my chosen men: which of you is ready to hew through the rampart with the sword and storm the panic-stricken camp with me?",
 """Greenough sets a fresh opening mark at 146 with no closing mark at 145, as English printing does when one speech runs into a new paragraph: Turnus turns from the Trojans to his own men; l and i keep the mark. 'qui… apparat', 'who makes ready', 'qui' is the old interrogative for 'quis', 'who?', singular as 'which one of you?'. The print ends the sentence with a full stop; as a question it wants a question mark, and l and i give one, but an appeal ('you who…') is not impossible, so t keeps the print. 'ferro', 'with steel'. 'trepidantia castra', 'the panicking camp'. Elision 'mec(um) invadit'."""),
(149, 'in Teucros;',
 "Not of the arms for me of Vulcan, not of a thousand keels\nis there need against the Teucrians;",
 "I have no need of armour made by Vulcan, nor of a thousand ships, against the Trojans;",
 """'Non… mihi… est opus', 'there is no need to me', 'opus est' with the ablative of the thing needed ('armis', 'carinis'). 'armis… Volcani', 'arms of Vulcan', such as the god made for Achilles in the Iliad and has just made for Aeneas (Book 8): Turnus needs no divine armour. 'mille carinis', 'a thousand keels', the Greek fleet against Troy (as 2.198 'non mille carinae'). The repeated 'non… non' (anaphora). 'in Teucros', 'against the Trojans'. No elisions."""),
(152, 'condemur in alvo:',
 "let them add themselves forthwith, all\nthe Etruscans, as allies; darkness and the cowardly thefts\nof the Palladium, with slain the guards of the highest citadel,\nlet them not fear, nor in the horse's dark shall we hide belly:",
 "let all the Etruscans join them as allies at once; they need not fear darkness, or a coward's theft of the Palladium after the guards of the citadel's height are cut down, nor shall we hide in the dark belly of a horse:",
 """'addant se… socios', 'let them add themselves as allies', jussive subjunctive: Turnus has heard that Aeneas has gone to the Etruscans. 'tenebras et inertia furta Palladii', 'darkness and the cowardly theft of the Palladium', the image of Pallas that Diomedes and Ulysses stole by night, killing the guards; 151 repeats 2.166. 'furta', plural for singular. 'caesis… custodibus', ablative absolute. The Latin Library prints 'late' for 'summae', 'guards cut down far and wide'. 'ne timeant', jussive with 'ne'. 'condemur', future, 'we shall (not) hide'. 'equi… in alvo', 'in the horse's belly', the Trojan Horse. No elisions."""),
(153, 'circumdare muros.',
 "by daylight, openly, it is settled to with fire surround the walls.",
 "I am resolved to ring their walls with fire in daylight and in the open.",
 """'luce palam', 'by daylight, in the open', the reverse of the Greek tricks he has just named. 'certum est', 'it is settled', 'I am resolved', with the infinitive 'circumdare'. 'igni circumdare muros', 'to surround the walls with fire', 'igni' the ablative in '-i'. Turnus's plan for the morrow, an assault and burning. Elision 'cert(um) est'."""),
(155, 'distulit Hector in annum.',
 "Not that they with Danaans have business, I'll make sure, and Pelasgian youth,\nwill they say, whom to the tenth put off Hector, year.",
 "I'll see to it that they do not say they are dealing with Greeks and Pelasgian boys, whom Hector held off until the tenth year.",
 """'faxo', an old future perfect of 'facio' (= 'fecero'), 'I'll make sure', with a bare subjunctive 'ferant', 'they shall say', and no 'ut'. 'haud sibi… rem esse cum Danais', 'that they have no business with Danaans', accusative and infinitive; 'rem esse cum' is 'to have to deal with'. 'pube Pelasga', 'Pelasgian youth', the Greeks under an old name. 'decumum… in annum', 'to the tenth year', enclosing the clause: Hector kept the Greeks off for nine years before Troy fell. 'decumum' is Greenough's spelling of 'decimum', the form the Latin Library prints. Elision 'fax(o) et'."""),
(158, 'pugnam sperate parari.”',
 "Now then, since the better part is spent of the day,\nfor what remains, glad at well done things, your bodies\ntend, men, and battle expect to be readied.”",
 "Now then, since the better part of the day is spent, for what is left of it see to your bodies, men, rejoicing in what has gone well, and expect that battle is preparing.”",
 """'Nunc adeo', 'now then', 'adeo' pointing up 'nunc'. 'melior… pars acta (est) diei', 'the better part of the day is spent'. 'quod superest', 'as to what is left', an accusative of respect. 'laeti bene gestis… rebus', 'glad at things well done', ablative of cause; the burning of the ships has failed, but Turnus calls the day a success. 'corpora procurate', 'take care of your bodies', with food and rest. 'sperate', 'expect', 'spero' of anticipation rather than wish. 'pugnam… parari', 'that a battle is being got ready', accusative and infinitive. Turnus's speech ends, and Greenough closes the mark. Elision 'vir(i) et'."""),
(160, 'cingere flammis.',
 "Meanwhile with sentries' watches to blockade the gates\nthe charge is given to Messapus, and the walls to ring with flames.",
 "Meanwhile the task of blockading the gates with lines of sentries and ringing the walls with watch-fires was given to Messapus.",
 """'Interea', 'meanwhile', the narrative resumes. 'cura datur Messapo', 'the charge is given to Messapus', with two infinitives explaining it, 'obsidere' and 'cingere'. 'vigilum excubiis', 'with the watches of sentries', 'excubiae' being guard-posts kept through the night (from 'ex' + 'cubo', lying out). 'moenia cingere flammis', 'to ring the walls with flames', watch-fires, so that no one can slip out unseen. Elisions 'vigil(um) excubiis', 'Messap(o) et'."""),
(163, 'auroque corusci.',
 "Twice seven Rutulians, the walls who with soldiery should guard,\nare chosen; but them a hundred each, each one, follow,\ncrimson in crests, young men, and with gold flashing.",
 "Fourteen Rutulians were picked to guard the walls with their troops, and each was followed by a hundred young men, crimson-crested and flashing with gold.",
 """'Bis septem', 'twice seven', the poetic way of saying fourteen. 'qui… servent', 'who should guard', a relative clause of purpose. 'milite', 'with soldiery', the collective singular. 'delecti (sunt)', 'are chosen'. 'ast', an archaic 'at', 'but'. 'centeni', 'a hundred apiece', the distributive numeral, with 'quemque', 'each one'. 'purpurei cristis', 'crimson in their crests', ablative of respect; 'corusci', 'flashing', with 'auro'. Elision 'delect(i) ast'."""),
(165, 'crateras aenos.',
 "They run about and vary their turns, and sprawled over the grass\nindulge in wine and tip up the mixing-bowls of bronze.",
 "They run to and fro and take turns at the watch, and lying stretched on the grass they give themselves to wine and tip up the bronze mixing-bowls.",
 """'Discurrunt', 'they run this way and that', to their posts. 'variant… vices', 'they vary their turns', they relieve one another in shifts. 'fusi per herbam', 'poured out over the grass', sprawled at ease. 'indulgent vino', 'they indulge in wine', the dative with 'indulgeo'. 'vertunt crateras', 'they turn up the mixing-bowls', draining them; 'crateras' is the Greek accusative plural of 'crater', the bowl in which wine was mixed with water. 'aenos', 'bronze', the poetic form of 'aeneos', three syllables. Elision 'vin(o) et'."""),
(167, 'insomnem ludo.',
 "Blaze the fires, the night the watch draws out,\nsleepless, in play.",
 "Their fires blaze, and the watch spends a sleepless night at play.",
 """'Conlucent', 'shine out together', 'collucent' with the prefix unassimilated. 'noctem… insomnem', 'the sleepless night', the adjective carried over the line end. 'custodia', 'the guard', the watchmen collectively. 'ducit', 'draws out', 'spends'. 'ludo', 'in play', gaming with dice. 167 is a half-line, one of the unfinished lines Virgil left in the poem (more than fifty); it closes a paragraph. The careless Rutulian watch is the opening Nisus will see (189). No elisions."""),
(171, 'tela gerunt.',
 "These things from above, from the rampart, watch the Trojans, and in arms\nthe heights hold; and also anxious with fear the gates\nthey test, and gangways and battlements join,\nweapons they carry.",
 "The Trojans watch all this from the top of their rampart and hold the heights in arms; anxious with fear, they test the gates as well, link gangways and battlements, and carry weapons.",
 """A new paragraph in Greenough. 'Haec', 'these things', the Rutulian camp below. 'super e vallo', 'from above, off the rampart', 'super' as an adverb. 'armis alta tenent', 'hold the heights with arms', man the top of the wall. 'nec non', 'and also', two negatives making a strong positive. 'explorant', 'test', try the bars. 'pontis', 'gangways', accusative plural in '-is': bridges from tower to tower, joined to the 'propugnacula', 'battlements'. 'tela gerunt', 'carry weapons', a short close (asyndeton). 'Troes', two syllables. Elision 'pontisqu(e) et'."""),
(173, 'esse magistros.',
 "Urges them on Mnestheus, and keen Serestus,\nwhom father Aeneas, if ever adversity should call,\nas rulers of the young men and of affairs gave to be masters.",
 "Mnestheus presses them on, and fierce Serestus, the men whom father Aeneas had appointed to govern the young troops and direct affairs if ever misfortune should call.",
 """'Instat', 'presses on', drives the work. Mnestheus was a captain in the boat-race of Book 5, said there to be the ancestor of the Roman Memmii (5.117). 'pater Aeneas', 'father Aeneas', his title as head of his people. 'siquando', Greenough's spelling of 'si quando', 'if ever'; 'adversa vocarent', 'adverse things should call', a subjunctive standing for a future in Aeneas's own orders. 'dedit esse', 'gave to be', appointed, with the infinitive. 'rectores… magistros', 'governors… masters', predicative. Elisions 'siquand(o) adversa', 'iuven(um) et'."""),
(175, 'tuendum est.',
 "The whole along the walls legion, having drawn by lot the danger,\nkeeps watch and works its turns, what each must guard.",
 "All along the walls the whole legion keeps watch, each having drawn his share of danger by lot, and takes its turns at the post each man must guard.",
 """'Omnis… legio', 'the whole legion', a Roman word for the Trojan force. 'sortita periclum', 'having drawn the danger by lot', 'sortior' a deponent, so the perfect participle is active; 'periclum' is the short form of 'periculum'. 'excubat', 'keeps watch', lies out at night. 'exercet vices', 'performs its turns', as at 164. 'quod cuique tuendum est', 'what is to be guarded by each', a gerundive of obligation with the dative of the agent: each man at his own post. Elision 'tuend(um) est'."""),
(178, 'levibusque sagittis;',
 "Nisus was of the gate the guard, keenest in arms,\nson of Hyrtacus, as comrade to Aeneas whom had sent Ida,\nthe huntress, with javelin quick and with light arrows;",
 "Nisus was the guard at one gate, a fierce fighter, the son of Hyrtacus; Ida the huntress had sent him to be Aeneas's comrade, swift with the javelin and the light arrow;",
 """A new paragraph in Greenough, and a new story: Nisus and Euryalus were the friends of the foot-race in Book 5 (5.294–361). 'acerrimus armis', 'keenest in arms', 'armis' ablative of respect. 'Hyrtacides', 'son of Hyrtacus', a Greek patronymic. 'comitem Aeneae', 'as comrade to Aeneas', predicative. 'Ida venatrix', 'Ida the huntress': either Mount Ida, the hunting-ground that bred him, or a nymph of that name, his mother; commentators divide. 'iaculo… levibusque sagittis', 'with javelin and light arrows', ablative of respect with 'celerem'. Elision 'comit(em) Aeneae'."""),
(181, 'intonsa iuventa.',
 "goes beside him as comrade Euryalus, than whom fairer another\nthere was not of Aeneas's men, nor put on Trojan arms,\nhis face, a boy, with the first marking unshorn youth.",
 "at his side, his comrade, went Euryalus; no one among Aeneas's men was more beautiful, nor did a fairer put on Trojan armour: a boy, whose unshaven cheeks showed the first down of youth.",
 """'it iuxta comes', 'goes beside (him) as comrade'. 'quo pulchrior alter non fuit', 'than whom no other was more beautiful', 'quo' ablative of comparison; 'Aeneadum' = 'Aeneadarum', 'of Aeneas's people', genitive plural in '-um'. 'neque induit', 'nor put on', with 'alter' as subject: no fairer man ever wore Trojan arms. 'ora… intonsa', 'unshorn face', set apart, 'ora' plural for singular; 'signans… prima iuventa', 'marking with first youth', the first beard. 'it' could be the Latin Library's 'et', 'and beside him (was)', a slight change. Elision 'nequ(e) induit'."""),
(182, 'in bella ruebant:',
 "To them love one there was, and side by side into wars they rushed:",
 "One love bound the two, and they charged into battle side by side:",
 """'His amor unus erat', 'to these there was one love', the dative of possession again: each loved the other, and the two shared one devotion. The line is much quoted; Book 5 already called Nisus's love for the boy 'amore pio', 'a dutiful love' (5.296). 'pariter', 'side by side', 'equally'. 'in bella ruebant', 'they would rush into wars', the imperfect of habit; 'bella' plural for singular. Elision 'pariterqu(e) in'."""),
(183, 'statione tenebant.',
 "then too in shared the gate watch they were holding.",
 "then too they were holding a gate on a shared watch.",
 """'tum quoque', 'then too', on this night as always. 'communi… statione', 'on a shared post', ablative of manner, enclosing 'portam'; 'statio' is a military post, a sentry station. 'tenebant', 'they were holding', the imperfect of the scene. The two lines (182–183) make a small portrait before the dialogue that follows. No elisions."""),
(185, 'dira cupido?',
 "Nisus says: “Is it the gods this ardour to our minds add,\nEuryalus, or to each his own becomes a god dread desire?",
 "Nisus said: “Euryalus, do the gods set this ardour in our minds, or does every man make a god of his own fierce longing?",
 """Nisus's speech opens (184–196). 'Dine' = 'di' + '-ne', the question particle on the emphatic word: 'is it the gods who…?'; 'di… an…', 'whether… or…', a double question. 'ardorem', 'burning eagerness'. 'mentibus', dative with 'addunt'. 'sua cuique… dira cupido', 'his own dread desire to each', enclosing 'deus fit', 'becomes a god'; 'cupido' is feminine here ('dira'), though as the god it is masculine. A much-quoted line: is a great impulse from heaven, or only our own craving made divine? Elisions 'Din(e) hunc', 'Euryal(e) an'."""),
(187, 'contenta quietest.',
 "Either a battle or something long now to attack, great,\nmy mind ponders, nor with peaceful is it content quiet.",
 "For a long while now my mind has been set on some fight or some great venture, and it cannot rest content in quiet and calm.",
 """'Aut pugnam aut aliquid… magnum', 'either battle or something great', the objects of 'invadere', 'to rush upon', 'undertake'. 'iamdudum… agitat', 'has long been turning over', the present with 'iamdudum' for an action that began in the past and goes on. 'mens… mihi', 'my mind', 'mihi' a dative of reference. 'placida… quietest', 'with calm quiet', ablative with 'contenta'; 'quietest' is Greenough's way of writing 'quiete est' with the 'e' of 'est' run in (prodelision), 'quiete est' in the Latin Library. Elisions 'pugn(am) aut', 'iamdud(um) invadere'."""),
(188, 'fiducia rerum.',
 "You see what the Rutulians holds, confidence in affairs.",
 "You see how sure of themselves the Rutulians are.",
 """'Cernis', 'you see', the evidence before them. 'quae… fiducia', 'what confidence', the subject of 'habeat', a subjunctive in an indirect question. 'Rutulos habeat', 'possesses the Rutulians', the feeling holding them, a Latin turn where English says 'the Rutulians have'. 'rerum', 'in (their) affairs', objective genitive: in their situation. The point is their overconfidence, which makes them careless. No elisions."""),
(190, 'silent late loca:',
 "The lights, few, glimmer; with sleep and wine loosened\nthey have lain down; silent far and wide the places are:",
 "Their lights are few and flickering; slack with sleep and wine they lie stretched out; the whole place is silent far and wide:",
 """'Lumina rara', 'lights few and scattered', the watch-fires now dying. 'micant', 'glimmer'. 'somno vinoque soluti', 'loosened by sleep and wine', ablatives of cause; the phrase recurs in Nisus's report to the leaders (236). 'procubuere' = 'procubuerunt', 'they have lain down', the '-ere' perfect. 'silent late loca', 'the places are silent far and wide'. Three short clauses without connectives (asyndeton): the scene through Nisus's eyes. No elisions."""),
(191, 'sententia surgat.',
 "learn further\nwhat I am pondering and what now in my mind the thought rising.",
 "now hear what I am weighing and what plan is rising in my mind.",
 """'percipe', 'take in', 'hear'. 'porro', 'further', 'next', moving on from the scene to the plan. 'quid dubitem', 'what I am pondering', 'dubito' in its sense of 'turn over', 'consider', not 'doubt'; 'dubitem' and 'surgat' are subjunctives in indirect questions. 'animo', 'in my mind', locative ablative. 'sententia', 'a thought', 'resolve'; it 'rises' as if of its own accord. Elision 'dubit(em) et'."""),
(193, 'certa reportent.',
 "That Aeneas be summoned all, both the people and the fathers,\ndemand, and that men be sent who sure news may bring back.",
 "Everyone, the people and the fathers alike, is demanding that Aeneas be called back, and that men be sent to bring him sure news.",
 """'Aenean', Greek accusative of 'Aeneas', subject of 'acciri', 'to be summoned', a passive infinitive after 'exposcunt', 'demand'; 'mitti', the second infinitive. 'populusque patresque', 'both the people and the fathers', the double '-que', with a Roman ring: the people and the senate, the 'patres', as if the camp were Rome. 'omnes', 'all', the subject, with 'populusque patresque' in apposition. 'qui… reportent', 'who may bring back', a relative of purpose; 'certa', 'sure things', definite news. 'Aenean' ends in '-n', so no elision before 'acciri'. Elision 'accir(i) omnes'."""),
(196, 'moenia Pallantea.”',
 "If to you what I ask they promise (for to me of the deed\nthe fame is enough), under that mound I think I can find\na way to the walls and the ramparts of Pallanteum.”",
 "If they promise you what I ask (for the glory of the deed is enough for me), I believe I can find a way under that hill to the walls and fortress of Pallanteum.”",
 """'Si tibi… promittunt', 'if they promise to you': Nisus means the reward to go to Euryalus. 'nam mihi facti fama sat est', 'for to me the fame of the deed is enough'. 'tumulo… sub illo', 'under that mound', a rise he points to, enclosing 'videor reperire'. 'videor… posse', 'I seem to be able', 'I think I can'. 'Pallantea', 'of Pallanteum', Evander's town where Aeneas went in Book 8, an adjective here with 'moenia'. Nisus's speech ends, and Greenough closes the mark. Elision 'vi(am) ad'."""),
(198, 'adfatur amicum:',
 "Stood stunned, by a great for praises struck love,\nEuryalus; at once with these his burning addresses friend:",
 "Euryalus stood stunned, struck by a great love of glory, and at once he spoke to his ardent friend with these words:",
 """'Obstipuit', 'was stunned', placed first, before its subject: 'Euryalus', set at the start of the next line. 'magno laudum… amore', 'by a great love of praise', enclosing 'percussus', 'struck'; 'laudes', plural, 'glory'. 'his (dictis)', 'with these words', the noun left out. 'ardentem… amicum', 'his burning friend', enclosing 'adfatur', 'addresses' (= 'affatur', the prefix unassimilated). Nisus burns with his plan; Euryalus catches fire from him. Elision 'ardent(em) adfatur'."""),
(200, 'Nise, fugis?',
 "“Me then as comrade to the highest to join ventures,\nNisus, you shun?",
 "“So, Nisus, you refuse to take me as your partner in so great a venture?",
 """Euryalus's speech opens (199–206). 'Mene… fugis?', 'do you shrink from (letting) me…?', 'me' with '-ne', the question on the emphatic word; 'fugio' with the infinitive, 'avoid', 'refuse'. 'socium', predicative, 'as comrade'. 'summis… rebus', 'to the highest deeds', dative with 'adiungere', 'to join'; 'adiungere' begins with a consonantal i after the prefix, ad-yun-ge-re. 'igitur', 'then', drawing his conclusion from Nisus's offer of the reward to him. Elision 'Men(e) igitur'."""),
(200, 'pericula mittam?',
 "Alone you into such dangers am I to send?",
 "Am I to let you go into such dangers alone?",
 """'Solum te… mittam?', 'am I to send you alone?', a deliberative subjunctive, a question of what one should do. 'Solum', set first for emphasis. 'tanta pericula', 'such great dangers', into which 'in' leads. The monosyllable 'te' is elided before 'in', a thing Virgil allows with pronouns like 'me' and 'te'. Elision 't(e) in'."""),
(204, 'fata extrema secutus:',
 "Not so me my father, in wars practised, Opheltes,\nthe Argive terror amid and Troy's sufferings\nraised, taught, nor with you such things have I done,\ngreat-hearted Aeneas and fortunes the last having followed:",
 "Not in that way did my father Opheltes, a man practised in war, raise and teach me, born amid the terror of the Greeks and the agonies of Troy; nor have I acted so with you, since I followed great-hearted Aeneas and his fortunes to the last:",
 """'Non ita… erudiit', 'did not teach (me) thus'. 'sublatum', 'taken up', the father lifting a newborn to own it as his. 'Argolicum terrorem inter', 'amid the Argive terror', 'inter' placed after its noun (anastrophe): he was born during the siege. Opheltes is named only here. 'nec tecum talia gessi', 'nor have I behaved so with you', as a coward. 'magnanimum Aenean', Greek accusative. 'fata extrema', 'the last fortunes', the worst of the wanderings. Elisions 'terror(em) inter', 'sublat(um) erudiit', 'magnanim(um) Aenean', 'fat(a) extrema'."""),
(206, 'tendis, honorem.”',
 "there is here, there is a spirit of the light scornful, and that\nwhich with life well thinks to be bought, toward which you strain, honour.”",
 "here, here is a spirit that scorns the light of life, one that thinks the honour you are reaching for well bought at the price of life.”",
 """'est hic, est animus', 'here is, here is a spirit', 'hic' the adverb, 'here' (in me); the doubled 'est' insists. 'lucis contemptor', 'a despiser of the light', of life itself. 'qui… credat', 'which thinks', a relative clause of characteristic, 'the kind that thinks'. 'istum… honorem', 'that honour of yours', enclosing the relative clause; 'iste' of the person spoken to. 'vita… emi', 'to be bought with life', 'vita' ablative of price. 'quo tendis', 'toward which you strive'. Euryalus's speech ends, and Greenough closes the mark. No elisions."""),
(209, 'aspicit aequis.',
 "Nisus to this: “Indeed about you nothing such did I fear,\nnor was it right, no; so may me bring back to you great, triumphant,\nJupiter, or whoever with eyes these things looks on fair.",
 "Nisus answered: “Indeed I had no such fear of you, nor would it have been right — no; so surely may great Jupiter, or whatever god looks on this with kindly eyes, bring me back to you in triumph.",
 """Nisus's reply opens (207–218). 'Nisus ad haec (respondit)', the verb of speaking left out, as so often. 'nil tale', 'nothing of the kind', that you would hang back. 'nec fas (erat)', 'nor was it right'; 'non' repeated, 'no!', for emphasis. 'ita me referat… Iuppiter', 'so may Jupiter bring me back', an oath in the form of a wish: as surely as I hope to return, I speak the truth. 'ovantem', 'rejoicing', in triumph. 'quicumque… aspicit', 'whoever looks on', some god. 'oculis… aequis', 'with fair eyes', enclosing 'haec aspicit'. Elision 'quicumqu(e) oculis'."""),
(212, 'superesse velim;',
 "But if anyone, as many you see in a crisis such,\nif anyone to ruin should sweep, either chance or a god,\nyou to survive I would wish;",
 "But if anything — and you see how much can happen in a crisis like this — if any chance or any god should sweep me to disaster, I would want you to live on;",
 """'Sed siquis… siquis', 'but if any… if any', repeated; 'siquis' is Greenough's spelling of 'si quis', as the Latin Library prints it, 'quis' the indefinite after 'si'. 'quae multa vides discrimine tali', 'such things as you see (are) many in a crisis like this', a parenthesis. 'in adversum rapiat', 'should snatch (me) into disaster', a present subjunctive in a future condition. 'casusve deusve', 'either chance or god', the subject, the double '-ve'. 'te superesse velim', 'I would want you to survive', a potential subjunctive. No elisions."""),
(212, 'dignior aetas.',
 "your of life worthier age.",
 "your years have a better claim on life.",
 """'tua… aetas', 'your age', enclosing 'vita dignior'. 'vita', ablative with 'dignior', 'worthier of life': 'dignus' takes the ablative of what one deserves. Nisus is older, Euryalus barely past boyhood (181); the young have more of life still owed to them. The sentence is spare, without a connective: a reason flatly given, with the verb 'est' left out. No elisions."""),
(215, 'decoretque sepulchro.',
 "Let there be one who me, snatched from the fight or with a price ransomed,\nmay commit to the earth, or, if her usual way, Fortune it shall forbid,\nto me absent may bring offerings and honour me with a tomb.",
 "Let there be someone to rescue me from the fight or ransom me with a price and lay me in the earth, or, if Fortune forbids it as she does, to bring offerings to me in my absence and honour me with a tomb.",
 """'Sit qui… mandet… ferat… decoret', 'let there be one who may commit… bring… honour', a jussive with relative clauses of purpose. 'raptum pugna', 'snatched from the battle', the body recovered; 'pretio… redemptum', 'ransomed with a price'. 'mandet humo', 'commit to the ground'. 'solita… Fortuna', 'Fortune, as she is used to', taken here with 'Fortuna' (some take 'humo solita', 'the accustomed earth'). 'siqua', 'if in any way'. 'absenti', 'to me, absent', the body lost. 'inferias', 'offerings to the dead'. 'sepulchro', an empty tomb, Greenough's spelling of 'sepulcro'. Elisions 'solit(a) aut', 'siqu(a) id'."""),
(218, 'curat Acestae,”',
 "Nor to your mother, poor, of such let me be the cause, grief,\nwho you alone, boy, of many mothers, having dared,\nfollows, and of great cares not for the walls, Acestes.”",
 "And let me not be the cause of so much grief to your poor mother, who alone of many mothers has dared to follow you, my boy, and cares nothing for the walls of great Acestes.”",
 """The print has 'Acestae,”', a misprint for 'Acestae.”', corrected here: the speech ends and 'Ille' begins a new sentence. 'Neu… sim', 'and let me not be', a negative wish. 'tanti… doloris', 'of so much grief', enclosing 'sim causa'. 'quae… ausa', 'who, having dared', framing the line; 'sola… multis e matribus', 'alone of many mothers'. 'persequitur', 'follows (you) all the way'. 'magni… Acestae', 'of great Acestes', the Trojan-born king in Sicily, where in Book 5 the weary and the women stayed behind in a city named for him (5.715–718). No elisions."""),
(221, 'adceleremus, ”ait.',
 "He, though: “Reasons in vain you weave, empty,\nnor my now, changed, from its place resolve yields:\nlet us make haste,” he says.",
 "But Euryalus said: “You are weaving empty excuses to no purpose; my mind is not changed and will not give ground: let us be quick,” he said.",
 """The print has 'adceleremus, ”ait', a misprint for 'adceleremus,” ait', corrected here: the closing mark is joined to 'ait' (as 9.52). 'Ille autem (respondit)', the verb of speaking left out again. 'Causas… inanis', 'empty reasons', 'inanis' accusative plural in '-is'; 'nectis', 'you weave', a chain of pretexts. 'nequiquam', 'in vain'. 'mea… sententia', 'my resolve', enclosing 'iam mutata loco'; 'mutata', 'changed'; 'loco cedit', 'yields from its place', gives ground like a soldier. 'adceleremus', Greenough's spelling of 'acceleremus', hortatory subjunctive. Elision 'Ill(e) autem'."""),
(222, 'servantque vices:',
 "The watchmen at once he rouses; they\nsucceed and keep the turns:",
 "At once he woke the sentries, who took their places and kept the watch:",
 """'Vigiles', 'the watchmen', the relief, asleep until their turn. 'simul', 'at once', as he spoke. 'excitat', 'rouses', 'wakes', Euryalus or Nisus, the subject left loose as the two act together. 'illi succedunt', 'they come up in succession', take over the post. 'servant vices', 'keep the turns', man the watch in their place (as 164, 175). The quick short clauses carry the action straight on from the speech. No elisions."""),
(223, 'regemque requirunt.',
 "their post left,\nhe himself as comrade with Nisus walks, and the king they seek.",
 "leaving their post, Euryalus walked at Nisus's side, and they went to look for the prince.",
 """'statione relicta', ablative absolute, 'their post left behind', a breach a Roman would notice. 'ipse', 'he himself', Euryalus, who has had his way. 'comes Niso', 'as comrade to Nisus', 'Niso' dative with 'comes'. 'graditur', 'walks', 'steps out'. 'regem', 'the king', most take it of Ascanius, the prince in command in his father's absence, who receives them at 232–233; the leaders are in council (226–228). 'requirunt', 'they seek', the plural for the two together. Elision 'relict(a) ipse'."""),
]

P = A.part('aeneid-065'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
    if t.rstrip('”]')[-1] not in A.TERMINAL + ',': print('ENDING', ln, repr(t[-12:]))
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
